-- Rifts World Book 34: Northern Gun Two - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 3 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~337-northern-gun-2-npcs-c.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.
-- Northern Gun Two's notable gladiators, third batch: Maximilian "Black Knight"
-- Schroeder (p.29), Antoine "Ripper" Leroj (p.30) and Verlan "Omega" Jones
-- (p.30-31). Every figure in the three stat blocks was checked against 150-dpi
-- renders of printed p.29-31; none of the three blocks carries an M.D.C. by
-- Location table or an armour M.D.C. line. The pirate groups that start on p.31
-- and the Top Fifty list (p.22) are left on purpose. Each weapon of note's
-- damage and range come from its catalog row, since the blocks print none.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('ng-maximilian-schroeder', 'Maximilian "Black Knight" Schroeder', 'Tobias Jodl', 'Former Robodome Heavyweight Champion (Triax X-2500 Black Knight)', 'rifts', 'Human', '8th level Robot Combat Pilot (NGR) (as printed)', 8, 'Scrupulous', '53', '6 feet (1.83 m)', '235 lbs (106 kg)', '{"IQ":14,"ME":14,"MA":13,"PS":17,"PP":22,"PE":17,"PB":14,"Spd":10}', 50, 24, NULL, NULL, NULL, NULL, NULL, '{"attacks":5}', 'Hand to hand: martial arts, five attacks per melee when outside his robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Computer Operation","pct":85},{"name":"Electronic Countermeasures","pct":75},{"name":"Language: American","pct":91},{"name":"Language: Euro","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Navigation","pct":90},{"name":"Hover Craft (ground)","pct":98},{"name":"Jet Aircraft","pct":98},{"name":"Military: Jet Fighters","pct":98},{"name":"Robots & Power Armor","pct":97},{"name":"Radio: Basic","pct":90},{"name":"Sensory Equipment","pct":85},{"name":"Weapon Systems","pct":85}]', 'Skills of note only; the block prints no full list. The math and piloting skills carry their catalog names (printed as Math: Basic, Pilot: Hovercraft, Pilot: Jet Aircraft, Pilot: Jet Fighter and Pilot: Robots & Power Armor); Language: American has no catalog row and keeps its printed name. Without percentages: Robot Combat Elite: Black Knight, Robot Combat Elite: Dyna-Max, Robot Combat Elite: Gargoyle Stopper, Robot Combat Elite: Ulti-Max, Running, W.P. Energy Rifle and Hand to Hand: Martial Arts. The block lists no Robot Combat: Basic.', NULL, 'None.', 'None.', NULL, 'None.', 'Weapon of note: the TX-24 Ion Pulse Pistol. Body armor: T-42 Commando Scout armor (catalog row: T-42 Commando Scout). Machines: the X-2500 Black Knight, his signature robot, and a TC-R5 Gargoyle Stopper he had brought over from Europe for Middleweight bouts (no catalog row holds it). He owns an old Ulti-Max suit (catalog row: X-1000 Ulti-Max Power Armor) but leaves it unused so that no one takes him for Gerhardt Fulcon. Vehicles: hovercars and limousines only.', NULL, 'Cheerful and easygoing, he cares more about giving the crowd a spectacle than about winning the bout. That order of priorities has lost him a title or two, but the Robodome''s producers love him for it, and fans know any match he is in will be worth watching.', 'Verlan "Omega" Jones and Gerhardt Fulcon, his companions on Ishpeming''s club and restaurant scene (from Verlan Jones''s entry, p.31; the block prints no allies line).', NULL, 'One of the best-loved Robo-Gladiators of the past ten years, known for a flamboyant fighting style, his accent and a rakish reputation. He left the New German Republic for North America in 97 P.A. and inside a couple of years had a place on the circuit, helped by the unmistakable Triax Black Knight he fights in. A former Heavyweight Champion who lost the belt some years ago, he is content to keep drawing bouts against the top-ranked fighters while a title rematch is withheld from him, and drops to Middleweight now and then for a change. A middle-aged gentleman carrying a little extra weight, with wavy silver hair, still fit for his years and showing no sign of slowing. Also known as the Black Knight and Big Max; the block gives his real name as Tobias Jodl.', 'Rifts World Book 34: Northern Gun Two p.29'),
('ng-antoine-leroj', 'Antoine "Ripper" Leroj', 'Antoine Leroj', 'Robodome Robo-Gladiator sponsored by Wilk''s Laser Technologies', 'rifts', 'Human', '5th level Robo-Gladiator (as printed)', 5, 'Anarchist', '32', '6 feet (1.83 m)', '172 lbs (77 kg)', '{"IQ":17,"ME":15,"MA":13,"PS":15,"PP":18,"PE":17,"PB":15,"Spd":14}', 31, 22, NULL, NULL, NULL, NULL, NULL, '{"attacks":5}', 'Hand to hand: basic, five attacks per melee when outside his robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Basic Mechanics","pct":50},{"name":"Computer Operation","pct":70},{"name":"Navigation","pct":65},{"name":"Performance","pct":60},{"name":"Robots & Power Armor","pct":88},{"name":"Public Speaking","pct":55},{"name":"Radio: Basic","pct":90},{"name":"Robot Mechanics","pct":40},{"name":"Sensory Equipment","pct":60},{"name":"Vehicle Armorer","pct":60},{"name":"Wardrobe & Grooming","pct":71},{"name":"Weapon Systems","pct":75}]', 'Skills of note only; the block prints no full list. Robots & Power Armor carries its catalog name (printed as Pilot: Robots & Power Armor). Without percentages: Robot Combat: Basic, Robot Combat Elite: Bison Battler, Robot Combat Elite: Forester Power Armor, Robot Combat Elite: Megabot, Robot Combat Elite: Volcano, W.P. Heavy M.D. Weapons and Hand to Hand: Basic.', NULL, 'None.', 'None.', NULL, 'A cybernetic multi-optic eye in place of his left eye.', 'Weapon of note: the Wilk''s 237 Backup laser pistol (catalog row: Wilk''s 237 "Backup"). Body armor: Crusader body armor (catalog row: Crusader - Full Environmental Body Armor; this book lists it as the Crusader EBA, p.55). Machines: the NG-M57-2N1 Megabot (catalog row: Megabot NG-M57-2N1 (Multibot reboot)), the NG-AX44 Bison Battler (no Northern Gun Two row holds it; Northern Gun One ships the Bison Combat Robot) and the NG Forester (catalog row: Forester Power Armor), turned out in Wilk''s colors and logos. Vehicle: a Speedster Hovercycle (catalog row: Speedster Hovercycle) for getting around.', NULL, 'Comes across as stern and humorless, but the gravity is a running bit that falls away once people know him. Among Robo-Gladiators he is notorious for pranks and practical jokes, and his humor has more than once nearly had him barred from the arena.', 'Wilk''s Laser Technologies, his employer and sponsor, which pays for his pit crew and his robots'' repairs (from the text; the block prints no allies line).', NULL, 'A Quebecois soldier who became a mercenary and then a security man for Wilk''s Laser Technologies, guarding its headquarters and riding escort on shipments through hostile country. Seeing Titan Robotics win attention with its sponsored gladiator team at the Ishpeming Robodome, he talked Wilk''s, a maker of laser tools and weapons with no robots or power armor of its own, into financing a robot or two in company livery to fix the Wilk''s name in the crowd''s mind. He is still on the payroll: Wilk''s covers his crew and repairs, he keeps his Robodome winnings, and in return he fights often and praises Wilk''s products whenever a reporter asks. Always sharply dressed and well groomed, with short black hair and dark eyes; he and his crew wear dark red, military-cut clothes. Known as Ripper Leroj, or just Ripper.', 'Rifts World Book 34: Northern Gun Two p.30'),
('ng-verlan-jones', 'Verlan "Omega" Jones', 'Verlan Jones', 'Reigning Robodome Heavyweight Champion', 'rifts', 'Human', '9th level Robo-Gladiator (as printed)', 9, 'Unprincipled', '39 (looks more like 32)', '6 feet, 2 inches (1.88 m)', '212 lbs (96 kg)', '{"IQ":15,"ME":11,"MA":19,"PS":21,"PP":24,"PE":14,"PB":13,"Spd":12}', 43, 22, NULL, NULL, NULL, NULL, NULL, '{"attacks":6}', 'Hand to hand: expert, six attacks per melee when outside his robot. The block prints no combat bonuses, saving throws or Horror Factor, and none are derived here.', '[{"name":"Basic Mechanics","pct":70},{"name":"Computer Operation","pct":90},{"name":"Navigation","pct":85},{"name":"Performance","pct":85},{"name":"Robots & Power Armor","pct":97},{"name":"Public Speaking","pct":75},{"name":"Radio: Basic","pct":90},{"name":"Robot Mechanics","pct":60},{"name":"Sensory Equipment","pct":80},{"name":"Vehicle Armorer","pct":80},{"name":"Wardrobe & Grooming","pct":87},{"name":"Weapon Systems","pct":95}]', 'Skills of note only; the block prints no full list. Robots & Power Armor carries its catalog name (printed as Pilot: Robots & Power Armor). Without percentages: Robot Combat: Basic, Robot Combat Elite: Blocker, Robot Combat Elite: Super Max, Robot Combat Elite: Hunter Mobile Gun, Robot Combat Elite: Grizzly, Robot Combat Elite: Samson Power Armor, W.P. Heavy M.D. Weapons and Hand to Hand: Expert.', NULL, 'None.', 'None.', NULL, 'None.', 'Favorite personal weapon: the NG-45LP long pistol (catalog row: NG-45LP "Long Pistol"). Body armor: Bushman body armor (taken as the catalog row Bushman - Full Composite Environmental Body Armor, which this book lists as the Bushman Composite EBA, p.55), carrying his orange colors and claw markings. Machines: his main ring robot, the Omega Fist, a modified NG-V67 Grizzly (no Northern Gun Two row holds it; Northern Gun One ships the Grizzly Combat Robot); a customized NG-8000 Super Max (catalog row: Super Max NG-8000 Combat Robot); and an NG-V19 Blocker (Northern Gun One ships the Blocker Combat Robot). Vehicle: a Big Boss ATV (catalog row: Big Boss ATV) done up in his team colors, which he drives nearly everywhere in place of limousines or private cars.', NULL, 'In public he stays haughty, chilly and distant, above all toward fellow gladiators, but that is the ring villain carried outside the ring. Privately he is an ordinary, likable man, free with his time, warm and welcoming, though he is among the most famous people on the continent.', 'Gerhardt Fulcon and Maximilian Schroeder, whom he calls the Germans, his companions in Ishpeming''s fanciest clubs and restaurants; a large following of fans, many of them young (from the text; the block prints no allies line).', 'Sarah Seymour, a personal rival since she turned down his advances on joining the circuit, and now a threat to his belt; the bookies and Black Market bosses who lost heavily on his 107 P.A. title win, whose revenge his fame has so far held off (from the text; the block prints no enemies line).', 'A veteran of the Robodome. Early on he was promoted as the hometown hope and coming challenger, but he found his real success as the heel whom crowds secretly cheer, a dependable foil for clean-cut rivals in the scripted feuds, with a loyal fan base that prizes skill and showmanship. In 107 P.A. he crushed the reigning Heavyweight Champion in a bout he was meant to lose with grace; the betting interests lost a fortune, but the fame that came with the belt has kept their vengeance at bay, and he has now held the title for two years. Young fans who want a champion with attitude, and who dislike the Robodome''s drift toward bloodless family entertainment, back him in numbers. His main arena machine is the Omega Fist, a close-quarters brawler suited to the ring, and its bright orange scheme and bear-claw markings are repeated on his armor and his crew''s jumpsuits. A big, broad-shouldered man with a stormy look and an intimidating stare, usually wearing a goatee or mustache, his salt-and-pepper hair kept short; he dresses in combat boots and military uniforms, usually in team colors. Also called Omega Jones, Omega and the Raptor.', 'Rifts World Book 34: Northern Gun Two p.30-31');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'ng-maximilian-schroeder', 'TX-24 Ion Pulse Pistol', '2D4 M.D. single shot, or 4D6 M.D. three-shot pulse burst', 1, '500 feet (152 m)', 'Weapon of note; damage and range from its catalog row (Triax and the NGR p.144), the block prints none.', 0),
('notable_npc', 'ng-antoine-leroj', 'Wilk''s 237 "Backup"', '3D6 M.D. single blast, or 6D6 M.D. double blast', 1, '500 feet (152 m)', 'Weapon of note; damage and range from its catalog row (New West p.205), the block prints none.', 0),
('notable_npc', 'ng-verlan-jones', 'NG-45LP "Long Pistol"', '5D6 M.D.', 1, '1,200 feet (365 m)', 'Favorite personal weapon; damage and range from its catalog row (Juicer Uprising p.71-76), the block prints none.', 0);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('ng-maximilian-schroeder', 'ng-antoine-leroj', 'ng-verlan-jones');
SELECT 'and the notables 3' AS assertion, count(*) AS got, 3 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('ng-maximilian-schroeder', 'ng-antoine-leroj', 'ng-verlan-jones');

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~337-northern-gun-2-npcs-c.sql');
